(function(){
  let initialTarget=true,canWrite=false;
  const ids=['research-form','research-fair-value','research-revision','research-fiscal-year','research-broken','research-rationale','research-source-url','research-as-of','research-expires-on','research-status'];
  const $=id=>document.getElementById(id); let generation=0;
  function symbol(){return $('symbol')?.value||'SPY'}
  function setStatus(s){const n=$('research-status');if(n)n.textContent=s}
  function ensure(){if($('research-form'))return $('research-form');const host=$('view-research');if(!host)return null;const s=document.createElement('section');s.className='evidence-panel research-record';s.innerHTML='<div class="section-head"><h2>我的研究记录</h2><span>人工研究 · 不自动编造</span></div><p class="research-help">填写已有依据；空值会保持未知。保存后会重新读取市场判断。</p><form id="research-form"><label>合理价值（美元/股）<input name="fairValue" id="research-fair-value" type="number" min="0.01" step="any"></label><label>同财年收入共识 30 日修正（%）<input name="revision" id="research-revision" type="number" min="-100" max="100" step="any"></label><label>财年（修正时必填）<input name="fiscalYear" id="research-fiscal-year" inputmode="numeric" maxlength="4"></label><label>基本面状态<select name="broken" id="research-broken"><option value="unknown">尚未核实</option><option value="no">未发现失效证据</option><option value="yes">已失效 / 重大下修</option></select></label><label class="research-wide">依据<textarea name="rationale" id="research-rationale" maxlength="2000" required></textarea></label><label class="research-wide">证据链接（HTTPS）<input name="sourceUrl" id="research-source-url" type="url" required></label><label>依据日期<input name="asOf" id="research-as-of" type="date" required></label><label>有效期至（最多 90 日）<input name="expiresOn" id="research-expires-on" type="date" required></label><button type="submit">保存研究记录</button><p id="research-status" role="status"></p></form></section>';host.append(s);return s.querySelector('form')}
  function fill(r){for(const [id,v] of [['research-fair-value',r?.fairValue],['research-revision',r?.revision],['research-fiscal-year',r?.fiscalYear],['research-broken',r?.broken||'unknown'],['research-rationale',r?.rationale],['research-source-url',r?.sourceUrl],['research-as-of',r?.asOf],['research-expires-on',r?.expiresOn]]){const n=$(id);if(n)n.value=v??''}}
  function disabled(v){$('research-form')?.querySelectorAll('input,select,textarea,button').forEach(n=>n.disabled=v)}
  async function load(){const g=++generation, sym=symbol();fill(null);disabled(true);setStatus('正在读取研究记录…');try{const [r,access]=await Promise.all([fetch('/api/research?symbol='+encodeURIComponent(sym),{cache:'no-store'}),fetch('/api/access',{cache:'no-store'}).then(r=>r.ok?r.json():{}).catch(()=>({}))]);canWrite=access.canWriteResearch===true;const d=await r.json();if(g!==generation||sym!==symbol())return;if(!r.ok)throw Error(d.error||'读取失败');fill(d.record);setStatus(!canWrite?'只读分享 · 仅网站所有者可以保存研究。':d.status==='expired'?'记录已过期，可编辑后保存。':d.record?'已读取人工研究记录。':'尚无记录，请按已有证据填写。')}catch(e){if(g===generation)setStatus(String(e.message||'暂时无法读取研究记录。'))}finally{if(g===generation){disabled(!canWrite);if(initialTarget){initialTarget=false;const target=document.getElementById(location.hash.slice(1));if(new URLSearchParams(location.search).get('view')==='research'&&target&&$('research-form').contains(target)){target.focus({preventScroll:true});target.scrollIntoView({block:'center'});}}}}}
  async function save(e){e.preventDefault();if(!canWrite){setStatus('只读分享 · 无法保存研究。');return;}const sym=symbol(),f=new FormData(e.currentTarget),payload={fairValue:f.get('fairValue')===''?null:Number(f.get('fairValue')),revision:f.get('revision')===''?null:Number(f.get('revision')),fiscalYear:f.get('fiscalYear')||null,broken:f.get('broken'),rationale:f.get('rationale'),sourceUrl:f.get('sourceUrl'),asOf:f.get('asOf'),expiresOn:f.get('expiresOn')},g=++generation;disabled(true);setStatus('正在保存…');try{const r=await fetch('/api/research?symbol='+encodeURIComponent(sym),{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(payload)});const d=await r.json();if(g!==generation||sym!==symbol())return;if(!r.ok)throw Error(d.error||'保存失败');fill(d.record);setStatus('已保存。正在刷新市场判断…');if(typeof window.refresh==='function')await window.refresh();else if(typeof refresh==='function')await refresh();if(g===generation&&sym===symbol())setStatus('已保存，市场判断已刷新。')}catch(err){if(g===generation)setStatus(String(err.message||'保存失败'))}finally{if(g===generation)disabled(false)}}
  function init(){const form=ensure();if(!form)return;form.addEventListener('submit',save);if(new URLSearchParams(location.search).get('view')==='research'&&typeof showView==='function'){showView('research');form.setAttribute('tabindex','-1');form.scrollIntoView({block:'start'});}$('symbol')?.addEventListener('change',load);load()}
  window.ResearchUI={load,save}; if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init,{once:true});else init();
})();
